scriptdefs
= FortreeCity_House1_EventScript_ExpertF
msgbox	Trading POKéMON with others…It's as if you're trading your own memories with other people.
end
= FortreeCity_House1_EventScript_Zigzagoon
lock
faceplayer
waitse
playmoncry SPECIES_ZIGZAGOON CRY_MODE_NORMAL
msgbox	ZIGZAGOON: Gumomoh?
waitmoncry
release
end
= FortreeCity_House1_EventScript_Trader
lock
faceplayer
goto_if_set FLAG_FORTREE_NPC_TRADE_COMPLETED FortreeCity_House1_EventScript_TradeCompleted
setvar VAR_0x8008 INGAME_TRADE_PLUSLE
copyvar VAR_0x8004 VAR_0x8008
specialvar VAR_RESULT GetInGameTradeSpeciesInfo
copyvar VAR_0x8009 VAR_RESULT
msgboxyesno	Wrooooaaar! I need it! I have to get me a STR_VAR_1! I'll do anything for it!…Uh… Did you hear that? My shout from the bottom of my heart?Having heard that, you will trade your STR_VAR_1 for my STR_VAR_2, won't you?
goto_if_eq VAR_RESULT NO FortreeCity_House1_EventScript_DeclineTrade
special ChoosePartyMon
copyvar VAR_0x800A VAR_0x8004
goto_if_eq VAR_0x8004 PARTY_NOTHING_CHOSEN FortreeCity_House1_EventScript_DeclineTrade
copyvar VAR_0x8005 VAR_0x800A
specialvar VAR_RESULT GetTradeSpecies
copyvar VAR_0x800B VAR_RESULT
goto_if_ne VAR_RESULT VAR_0x8009 FortreeCity_House1_EventScript_NotRequestedMon
copyvar VAR_0x8004 VAR_0x8008
copyvar VAR_0x8005 VAR_0x800A
special CreateInGameTradePokemon
special DoInGameTradeScene
bufferspeciesname STR_VAR_1 VAR_0x8009
msgbox	Oh, yeah, right on!STR_VAR_1, welcome! STR_VAR_2, you take care!
setflag FLAG_FORTREE_NPC_TRADE_COMPLETED
release
end
= FortreeCity_House1_EventScript_NotRequestedMon
bufferspeciesname STR_VAR_1 VAR_0x8009
msgbox	Uh, no, I don't think so. That isn't a STR_VAR_1.
release
end
= FortreeCity_House1_EventScript_DeclineTrade
msgbox	No? You won't trade me? Even after I bared my heart to you?
release
end
= FortreeCity_House1_EventScript_TradeCompleted
msgbox	I'm going to make VOLBEAT super strong from this moment on!I hope you do the same with PLUSLE!
release
end

